  var collectionFacets = function () {
    var $ajaxWrap = $('#js-collection');
    if (!$ajaxWrap.length) {
      return;
    }
    var base_url = location.origin + location.pathname;
    var urls = [];
    var responses = [];
    urls.push(base_url);
    responses.push($('#js-collection').html());
    function filterCollection(url) {
      var currentPath = window.location.pathname.split("?")[0];
      var finalUrl;
      if (url.toString().includes(currentPath)) {
        finalUrl = window.location.origin + url;
      } else {
        finalUrl = window.location.origin + currentPath + url;
      }
      if (urls.indexOf(finalUrl) > -1) {
        $ajaxWrap.html(responses[urls.indexOf(finalUrl)]);
        LazyLoading.refresh();
      } else {
        $.ajax({
          url: finalUrl,
          type: "GET",
          beforeSend: function beforeSend() {
            $ajaxWrap.find('.collection-grid').addClass('loading');
          },
          success: function success(res) {
            var ajaxHTML = $(res).find('#js-collection').html();
            $ajaxWrap.html(ajaxHTML);
            urls.push(finalUrl);
            responses.push(ajaxHTML);
            LazyLoading.update();
            StickToHeader.refresh();
            productCard.init();
          },
          error: function error(res) {
            console.log(res);
          }
        });
      }
      window.history.replaceState(null, null, finalUrl);
    }
    $('body').on('submit', 'form.col-facets', function (e) {
      e.preventDefault();
      var $this = $(this);
      var url = base_url;
      if ($this.serialize()) {
        url = '?' + $this.serialize();
      }
      filterCollection(url);
    });
    $('body').on('click', '.remove-filter', function () {
      var $this = $(this);
      filterCollection($this.data('remove'));
    });
    $('body').on('change', 'form.col-facets', function () {
      $('.col-facets__submit').click();
    });
    $('body').on('change', '.facet-filters__sort', function () {
      $('[name="sort_by"]').val($(this).val());
      $('.col-facets__submit').click();
    });
    $('body').on('click', '.filter legend', function () {
      var $is_active = $(this).closest('.filter').hasClass('active');
      $('.filter').removeClass('active');
      if (!$is_active) {
        $(this).closest('.filter').addClass('active');
      }
    });
    $('body').on('click', '.show-filters', function () {
      $('form.col-facets').toggleClass('active');
    });
  }();
  var predictiveSearch = function () {
    var $search = $('.js-site-search');
    var $searchForm = $('.js-site-search__form');
    var $searchInput = $('.js-site-search__input');
    var $searchIcon = $('.js-site-search__open');
    var $searchClose = $('.js-site-search__close');
    var $searchResults = $('.js-site-search__results');
    function close() {
      $search.fadeOut(function () {
        $searchInput.val('');
        $searchResults.removeClass('active');
      });
    }
    $searchClose.click(function () {
      close();
      siteOverlay.close();
    });
    $searchIcon.click(function () {
      siteOverlay.open();
      $search.fadeIn();
      $searchInput.focus();
    });
    function ajaxSearch(terms) {
      $.ajax({
        url: '/search/suggest',
        type: "GET",
        data: {
          q: terms,
          section_id: 'site-search',
          // resources[type]: 'query,product,collection,page,article',
          'resources[type]': 'query,product,page,article'
        },
        success: function success(res) {
          $searchResults.html($(res).find('#predictive-search-results').html());
          $searchResults.addClass('active');
        },
        error: function error(res) {
          console.log(res);
        }
      });
    }
    $searchInput.keyup(function (e) {
      if (e.keyCode == 13) {
        return;
      }
      ajaxSearch($searchInput.val());
    });
    $searchForm.submit(function (e) {
      e.preventDefault();
      ajaxSearch($searchInput.val());
    });
    $('body').on('click', '.js-site-search__suggestions button', function () {
      var val = $(this).text();
      $searchInput.val(val);
      ajaxSearch(val);
    });
    return {
      close: close
    };
  }();

