  var blogFilters = function () {
    var $filters = $('.tag-filters input');
    if (!$filters.length) {
      return;
    }
    $filters.change(function () {
      var filters = '';
      $filters.filter(':checked').each(function () {
        filters += $(this).val() + '+';
      });
      filters = filters.slice(0, -1);
      var redirect = $('#blog-tag-select').val();
      if (filters.length) {
        if (redirect.includes('tagged')) {
          redirect = redirect + '+' + filters;
        } else {
          redirect = redirect + '/tagged/' + filters;
        }
      }
      window.location.href = redirect;
    });
  }();
