var PreOrderNotification = function () {
  function decode(input) {
    var txt = document.createElement("textarea");
    txt.innerHTML = input;
    return txt.value;
  }
  document.addEventListener('variantChange', function (e) {
    var $section = $('.js-preorder-notification');
    if (!$section.length) {
      return;
    }
    var $po_message = productInfo.selectedVariant.preorder_message || false;
    if ($po_message) {
      var message = decode($po_message);
      $section.find('.js-preorder-notification__message').html(message);
      $section.removeClass('hidden');
    } else {
      $section.addClass('hidden');
    }
  }, false);
  var ModelCompare = function () {
    var $section = $('.model-compare');
    if (!$section.length) {
      return;
    }
    var $specCard = $section.find('.js-prodspec');
    $specCard.find('.js-prodspec__trigger').click(function () {
      $(this).closest('.js-prodspec').toggleClass('active');
    });
    $specCard.find('.js-prodspec__close').click(function () {
      $(this).closest('.js-prodspec').removeClass('active');
    });
    var swiper = new Swiper($section.find('.swiper').get(0), {
      init: false,
      slidesPerView: 1,
      spaceBetween: 16,
      scrollbar: {
        el: $section.find('.swiper-scrollbar').get(0)
      },
      breakpoints: {
        720: {
          slidesPerView: 2
        }
      }
    });
    if (window.innerWidth < 960) {
      swiper.init();
    }
  }();
  var AccordionTimeline = function () {
    var $section = $('.content-timeline');
    if (!$section.length) {
      return;
    }
    function initAutoTimeline($this) {
      var interval = 7000;
      var $slides = $this.find('.swiper-slide');
      var active_slide = 0;
      var timeline;
      $slides.find('.js-accordion-timeline__content').first().addClass('active').show();
      function resetTimeline() {
        timeline = setInterval(function () {
          active_slide = active_slide + 1 >= $slides.length ? 0 : active_slide + 1;
          // console.log(active_slide);

          $slides.removeClass('active').find('.accordion-timeline').removeClass('active');
          $slides.find('.accordion-timeline__content').slideUp();
          $slides.eq(active_slide).addClass('active').find('.accordion-timeline').addClass('active').find('.accordion-timeline__content').slideDown();
        }, interval);
      }
      resetTimeline();
      $this.hover(function (e) {
        var e_type = e.type;
        var $e = $(e.currentTarget);
        if (e_type == 'mouseenter') {
          clearInterval(timeline);
        } else {
          resetTimeline();
        }
      });
      $slides.click(function () {
        active_slide = $slides.index($(this));

        /* TODO: Finish this function.
         * take the index of the clicked slide and set it as the active slide
         * */
        $slides.removeClass('active').find('.accordion-timeline').removeClass('active');
        $slides.find('.accordion-timeline__content').slideUp();
        $slides.eq(active_slide).addClass('active').find('.accordion-timeline').addClass('active').find('.accordion-timeline__content').slideDown();
      });
    }
    $section.each(function () {
      var $this = $(this);
      var $accordions = $this.find('.js-accordion-timeline');
      var $slider = $this.find('.swiper');
      var timeline_delay = 5000;
      $slider.each(function () {
        var _this = $(this);
        var swiper = new Swiper(_this.get(0), {
          init: false,
          slidesPerView: 1
        });
        if (window.innerWidth < 960) {
          swiper.init();
        } else {
          initAutoTimeline(_this);
        }
      });
    });
  }();
  var AnimatedHero = function () {
    var $section = $('.animated-hero');
    if (!$section.length) {
      return;
    }
    gsap.registerPlugin(ScrollTrigger);
    var $content_main = $section.find('.animated-hero__content--main');
    var $content_dup = $section.find('.animated-hero__content--dup');
    var $bg_image = $section.find('.animated-hero__bg img');
    var $clip = $section.find('.animated-hero__clip');
    var hero_height = $section.innerHeight() - 200;
    var header_height = $('.gheader').innerHeight();
    var window_width = window.innerWidth;
    var window_width_20 = window_width * 0.1;
    gsap.set($clip, {
      clipPath: 'inset(' + hero_height + 'px ' + (window_width_20 - 1) + 'px 0px ' + (window_width_20 + 1) + 'px)',
      opacity: 1
    });
    var tl = gsap.timeline({
      scrollTrigger: {
        trigger: $section.get(0),
        start: 'top ' + header_height + 'px',
        end: 'bottom ' + header_height + 'px',
        scrub: true,
        pin: true
      }
    });
    tl.to($clip, {
      clipPath: 'inset(' + hero_height / 1.5 + 'px ' + (window_width_20 - 1) + 'px 0px ' + (window_width_20 + 1) + 'px)',
      duration: 4
    }, '1');
    tl.to($clip, {
      clipPath: 'inset(0px 0px 0px -1px)',
      duration: 4
    });
    tl.to($bg_image, {
      scale: 1.3,
      duration: 8
    }, '1');
  }();
  var ExpandingCards = function () {
    var $section = $('.expanding-cards');
    if (!$section.length) {
      return;
    }
    var $expcard = $section.find('.js-expcard');
    $expcard.find('.js-expcard__trigger').click(function () {
      $(this).closest('.js-expcard').toggleClass('active');
    });
    $expcard.find('.js-expcard__close').click(function () {
      $(this).closest('.js-expcard').removeClass('active');
    });
  }();
}();